# D=9 abelian-quotient bound: an abelian quotient Q of the Haar graph H(G,S), |S|=4 (0 in S), must satisfy
# |Q| <= |4D| where D = S - S and |4D| is the number of values of sums of 4 elements of D.
# The count is maximised by the free abelian group on s1,s2,s3 (S = {0,s1,s2,s3}); any Q generated by S is a quotient of it.
import itertools
gens = [(1,0,0),(0,1,0),(0,0,1)]
def add(x,y): return tuple(a+b for a,b in zip(x,y))
def neg(x): return tuple(-a for a in x)
def sub(x,y): return add(x,neg(y))
S = [(0,0,0)] + gens
D = set()
for s in S:
    for t in S:
        D.add(sub(s,t))
D = sorted(D)
print("|D| =", len(D))
R = {(0,0,0)}
for _ in range(4):
    R = {add(x,d) for x in R for d in D}
    print("reach within", 2*_+2, "steps: |sumset| =", len(R))
